const { ExprError } = require('./errors');

/** Parse a complete token sequence into an AST. Nodes retain operator columns. */
function parse(tokens) {
  let position = 0;
  const current = () => tokens[position];
  const take = () => tokens[position++];
  const is = value => current().value === value;
  const expect = value => {
    if (!is(value)) throw new ExprError(`Expected ${value}`, current().column);
    return take();
  };
  const binary = (operator, left, right) => ({ type: 'binary', operator, left, right });

  function isComparison() {
    const value = current().value;
    return value === '<' || value === '<=' || value === '>' ||
      value === '>=' || value === '==' || value === '!=';
  }

  function comparison() {
    const first = sum();
    if (!isComparison()) return first;
    const operands = [first];
    const operators = [];
    do {
      operators.push(take());
      operands.push(sum());
    } while (isComparison());
    return { type: 'comparison', operands, operators };
  }

  function sum() {
    let left = product();
    while (is('+') || is('-')) {
      const operator = take();
      left = binary(operator, left, product());
    }
    return left;
  }

  function product() {
    let left = unary();
    while (is('*') || is('/') || is('//') || is('%')) {
      const operator = take();
      left = binary(operator, left, unary());
    }
    return left;
  }

  function unary() {
    if (is('+') || is('-')) {
      return { type: 'unary', operator: take(), operand: unary() };
    }
    return power();
  }

  function power() {
    const left = primary();
    if (!is('**')) return left;
    const operator = take();
    return binary(operator, left, unary());
